;s:9:\"timestamp\";s:27:\"2022-09-11T16:45:02.237086Z\";s:6:\"source\";s:6:\"Google\";}i:2;a:6:{s:6:\"author\";s:11:\"Per Castell\";s:6:\"avatar\";s:125:\"https://lh3.googleusercontent.com/a-/ALV-UjXd-HihNKnzvo_md9ATAgBRmsN-6KslwuF3ok7680cviFVHfKGd5g=s128-c0x00000000-cc-rp-mo-ba6\";s:6:\"rating\";i:4;s:4:\"text\";s:118:\"We stopped to visit the toilet. These were clean and nice and everything works cost 5 php. Thanks for the cleanliness.\";s:9:\"timestamp\";s:27:\"2023-02-03T10:55:56.224297Z\";s:6:\"source\";s:6:\"Google\";}i:3;a:6:{s:6:\"author\";s:13:\"Tata Naloisap\";s:6:\"avatar\";s:122:\"https://lh3.googleusercontent.com/a-/ALV-UjX9C3pXbnSQpygDTuYf0oluiYjYlXdoQJXGMnb8jay3cEL5rmQ=s128-c0x00000000-cc-rp-mo-ba3\";s:6:\"rating\";i:5;s:4:\"text\";s:80:\"The staff was quite accommodating. Petron\'s parking lot is located near the sea.\";s:9:\"timestamp\";s:27:\"2025-02-24T18:08:53.507529Z\";s:6:\"source\";s:6:\"Google\";}i:4;a:6:{s:6:\"author\";s:13:\"Reymus Pambid\";s:6:\"avatar\";s:122:\"https://lh3.googleusercontent.com/a-/ALV-UjWIj8-Z3Aio8sjHwwVt5aspzwUV7Xm9wk1y_5fTZ8JX2o4_z4U=s128-c0x00000000-cc-rp-mo-ba4\";s:6:\"rating\";i:5;s:4:\"text\";s:9:\"Passer-by\";s:9:\"timestamp\";s:30:\"2026-05-25T08:47:23.639610584Z\";s:6:\"source\";s:6:\"Google\";}}s:17:\"editorial_summary\";N;s:6:\"source\";s:6:\"google\";}i:8;a:15:{s:2:\"id\";s:27:\"ChIJl_aJZzUVkTMR5jahR_6cGSE\";s:4:\"name\";s:21:\"CleanFuel Gas Station\";s:3:\"lat\";d:16.0522995;s:3:\"lng\";d:120.56514539999999;s:7:\"address\";s:44:\"3H28+W36, Binalonan, Pangasinan, Philippines\";s:8:\"category\";s:12:\"google_place\";s:4:\"type\";s:11:\"gas-station\";s:6:\"rating\";i:4;s:18:\"user_ratings_total\";i:34;s:7:\"reviews\";i:34;s:15:\"photo_reference\";s:478:\"places/ChIJl_aJZzUVkTMR5jahR_6cGSE/photos/AVoNoXSXO7mOr4Sn-6oYNeKj_-5Wdk_9pEVh1yD3Xdho4YxH5ecab1M8JuqLIakE76rUHJwPqO8O1DK25LD-nu4We1gdPL2PEewaxDCVasX2TIX9vbHWrz7bF_8opbG_h8CD42sQ0CAdR7T-HUlgQJwozOI5vUsjUg76cVJnfzMzpafw0xVbOUGLh9bth_5MHPLJgoX7B2PZdf10P8X9jI53b1OB